"""Machine-level lemmas for the round-2 end of T12a (specs evs_end.py), generated by mexp.py.
  python gen_machine_end.py OUT.v      (dev: a file on top of Dev.M)"""
import sys, time
from pathlib import Path
from evs_end import *
import mexp
mexp.MAXLEN = 200

EVENTS = ['E20', 'CONV0', 'CONV', 'Z0', 'Z1', 'EAT0', 'EAT1', 'EAT2', 'EAT3', 'EAT4', 'EAT5', 'SM3', 'F23', 'F24',
          'G1', 'G2', 'G3']
HALTS = ['HALT1', 'HALT2']


def halt_lemmas(name, S, out):
    tree = mexp.explore(S, None, splits=0)
    assert tree.get('halt') and all(it[0] != 'split' for it in tree['items'])
    g = mexp.Gen('X' + name)
    tac = ['intros.']
    for it in tree['items']:
        tac.append(g.stage(it[2], it[1], it[3]) if it[0] == 'ops' else g.use_loop(it[1]))
    end = tree['end']
    cn, vs = coqgen.free_vars(S, end)
    out += g.lemmas
    out.append('Lemma EV_%s : forall %s, %s -->* %s.\nProof.\n%s\n  finish_norm.\nQed.\n'
               % (name, ' '.join(cn + vs), coqgen.cfg_coq(S), coqgen.cfg_coq(end), coqgen.wrap(tac)))
    out.append('Lemma EV_%s_halted : forall %s, halted tm (%s).\nProof. intros. reflexivity. Qed.\n'
               % (name, ' '.join(cn + vs), coqgen.cfg_coq(end)))


def gen(events=None, halts=None):
    out = []
    t0 = time.time()
    for name in (EVENTS if events is None else events):
        S, T = EVE[name][:2]
        pos = frozenset(EVE[name][2]) if len(EVE[name]) > 2 else frozenset()
        t1 = time.time()
        tree = mexp.explore(S, T, splits=4, positive=pos)
        g = mexp.Gen('X' + name)
        r = mexp.rule_lemma('EV_' + name, S, T, tree, g, progress=False, positive=sorted(pos))
        out += g.lemmas + [r]
        print(name, '%.1fs' % (time.time() - t1), len(g.lemmas) + 1, 'lemmas', file=sys.stderr, flush=True)
    for name in (HALTS if halts is None else halts):
        halt_lemmas(name, EVE[name][0], out)
        print(name, 'done', file=sys.stderr, flush=True)
    print('generated in %.1fs, %d lemmas' % (time.time() - t0, len(out)), file=sys.stderr)
    return out


def machine_text(events=None, halts=None):
    pl.LEMMAS.clear()
    lem = gen(events, halts)
    return ('\n(** ** Crossing lemmas (generated) *)\n\n' + coqgen.crossing_lemmas()
            + '\n(** ** Machine-level lemmas of the round-2 end (generated by mexp.py) *)\n\n' + '\n'.join(lem))


if __name__ == '__main__':
    pre = ('(** * T12a round-2 end, machine part (development) *)\n\nFrom BB8 Require Import Individual122.\n'
           'From Dev Require Import M.\nFrom Coq Require Import Lia PeanoNat List.\nImport ListNotations.\n'
           'Set Default Goal Selector "!".\n')
    sel = sys.argv[2] if len(sys.argv) > 2 else 'all'
    if sel == 'small':
        text = pre + machine_text([e for e in EVENTS if not e.startswith('EAT')], HALTS)
    elif sel == 'eat':
        text = pre + machine_text([e for e in EVENTS if e.startswith('EAT')], [])
    else:
        text = pre + machine_text()
    Path(sys.argv[1]).write_text(text, newline='\n')
    print('wrote', sys.argv[1], len(text), 'bytes', file=sys.stderr)
